mapper.select:
SELECT PMCO, 
	   PMNM,
	   PMV1 pmv1,
	   PMV2 pmv2
  FROM PARAMETER
 WHERE PMCO <> '******'

   		AND PMST = #{sp.pmst}


   		AND PMKY = #{sp.pmky}


   		AND PMCO = #{sp.pmco}


   		AND PMV1 = #{sp.pmv1}


   		AND PMV2 = #{sp.pmv2}


   		AND PMV3 = #{sp.pmv3}


   		AND (PMNM LIKE '%' || #{sp.pmnm} || '%' OR PMCO LIKE '%' || #{sp.pmnm} || '%')

 ORDER BY PMCO ASC

		SELECT PMCO	pmco,
			   PMNM	pmnm,
			   PMV1 pmv1,
			   PMV2 pmv2
		  FROM PARAMETER
		 WHERE PMCO <> '******'
   		   AND PMKY = #{pmky}
   		   AND PMST = #{pmst}
   		   AND PMCO = #{pmco}
		 ORDER BY PMCO ASC
